<?php
namespace WPR_Static;
if (!defined('ABSPATH')) exit;
final class Admin {
    private static function tr(string $s):string{return __($s,'wpr-static');}
    private static function ru():bool{return str_starts_with(determine_locale(),'ru');}
    private static function t(string $en,string $ru):string{return self::ru()?$ru:$en;}
    private static function e(string $en,string $ru):void{echo esc_html(self::t($en,$ru));}
    private static function url(array $params=[]):string{return add_query_arg(array_merge(['page'=>'wpr-static'],$params),admin_url('admin.php'));}
    private static function allowed():void{if(!current_user_can('manage_options')||is_multisite())wp_die('Forbidden',403);}
    public static function init():void{
        add_action('admin_menu',static function(){add_menu_page('Static Site Generator for WordPress','Static Site Generator','manage_options','wpr-static',[self::class,'render'],'dashicons-database-export',82);});
        add_action('admin_enqueue_scripts',static function($hook){if($hook!=='toplevel_page_wpr-static')return;wp_enqueue_style('wpr-static',plugins_url('assets/admin.css',WPR_STATIC_FILE),[],WPR_STATIC_VERSION);wp_enqueue_script('wpr-static',plugins_url('assets/admin.js',WPR_STATIC_FILE),[],WPR_STATIC_VERSION,true);wp_localize_script('wpr-static','WPRStaticAdmin',['url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('wpr_static_tick')]);});
        add_action('admin_post_wpr_static_action',[self::class,'action']);add_action('wp_ajax_wpr_static_tick',[self::class,'tick']);
    }
    public static function tick():void{self::allowed();check_ajax_referer('wpr_static_tick','nonce');try{$id=absint($_POST['id']??0);if($id!==Engine::active())throw new \RuntimeException('BUILD_NOT_ACTIVE');try{Engine::tick($id,7);}catch(\Throwable $e){if($e->getMessage()!=='WORKER_BUSY')throw $e;}wp_send_json_success(Engine::stats($id));}catch(\Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
    private static function download(string $name,string $mime,string $content):void{nocache_headers();header('Content-Type: '.$mime);header('Content-Disposition: attachment; filename="'.$name.'"');echo $content;exit;}
    public static function action():void{
        self::allowed();check_admin_referer('wpr_static_action');$op=sanitize_key($_POST['op']??'');$id=absint($_POST['id']??0);$tab=sanitize_key($_POST['tab']??'overview');
        try{switch($op){case 'save':update_option('wpr_static_settings',Engine::clean(wp_unslash($_POST)),false);break;
            case 'doctor':$checks=Engine::doctor(array_replace(Engine::settings(),['frontend'=>true,'destination'=>rtrim(home_url('/'),'/')]));try{Frontend::assertCacheCompatible();$checks[]=['code'=>'FRONTEND_CACHE','level'=>'ok','message'=>'No conflicting advanced-cache.php detected.'];}catch(\Throwable $e){$checks[]=['code'=>'FRONTEND_CACHE','level'=>'error','message'=>$e->getMessage()];}set_transient('wpr_static_doctor_'.get_current_user_id(),$checks,600);$tab='doctor';break;
            case 'build':$id=Engine::start();$tab='overview';break;
            case 'enable_frontend':$id=Frontend::enable();$tab='overview';break;
            case 'rebuild_frontend':$id=Frontend::rebuild();$tab='overview';break;
            case 'disable_frontend':Frontend::disable();$tab='overview';$id=0;break;
            case 'auto_on':case 'auto_off':Frontend::setAuto($op==='auto_on');$tab='overview';break;
            case 'pause':case 'resume':case 'cancel':Engine::control($id,$op);break;
            case 'publish':Engine::publish($id);break;
            case 'delete':Engine::delete($id);$id=0;$tab='history';break;
            case 'export':$path=Engine::export($id);nocache_headers();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="wpr-static-'.gmdate('Y-m-d-His').'-'.$id.'.zip"');header('Content-Length: '.filesize($path));$f=fopen($path,'rb');while(!feof($f)){echo fread($f,1048576);if(connection_aborted())break;}fclose($f);exit;
            case 'report':Engine::build($id);global $wpdb;$t=Engine::table('tasks');$rows=$wpdb->get_results($wpdb->prepare("SELECT kind,state,path,http_status,bytes,sha256,error FROM $t WHERE build_id=%d ORDER BY id",$id),ARRAY_A);self::download('wpr-static-report-'.$id.'.json','application/json',wp_json_encode(['summary'=>Engine::stats($id),'tasks'=>$rows,'logs'=>Engine::logs($id,10000)],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));break;
            case 'manifest':Engine::validate($id);self::download('manifest-'.$id.'.json','application/json',file_get_contents(Storage::build($id).'/manifest.json'));break;
            default:throw new \RuntimeException('UNKNOWN_ACTION');}
            set_transient('wpr_static_notice_'.get_current_user_id(),['ok'=>true,'msg'=>self::t('Action completed.','Операция выполнена.')],60);
        }catch(\Throwable $e){set_transient('wpr_static_notice_'.get_current_user_id(),['ok'=>false,'msg'=>$e->getMessage()],60);}
        wp_safe_redirect(self::url(['tab'=>$tab,'id'=>$id]));exit;
    }
    private static function form(string $op,string $en,string $ru,int $id=0,string $tab='overview',bool $primary=false):void{echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="wpr-inline">';self::hidden($op,$id,$tab);echo '<button class="button '.($primary?'button-primary':'').'"'.(in_array($op,['delete','publish'],true)?' data-confirm="'.esc_attr(self::t('Continue?','Продолжить?')).'"':'').'>'.esc_html(self::t($en,$ru)).'</button></form>';}
    private static function hidden(string $op,int $id=0,string $tab='overview'):void{wp_nonce_field('wpr_static_action');foreach(['action'=>'wpr_static_action','op'=>$op,'id'=>$id,'tab'=>$tab] as $k=>$v)echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr((string)$v).'">';}
    private static function field(string $name,string $en,string $ru,$value,string $type='text',string $help=''):void{echo '<label class="wpr-field"><strong>'.esc_html(self::t($en,$ru)).'</strong>';if($type==='textarea')echo '<textarea name="'.esc_attr($name).'" rows="5" class="large-text code">'.esc_textarea($value).'</textarea>';else echo '<input type="'.esc_attr($type).'" name="'.esc_attr($name).'" value="'.esc_attr((string)$value).'" class="regular-text">';if($help)echo '<small>'.esc_html($help).'</small>';echo '</label>';}
    public static function render():void{
        self::allowed();$tab=sanitize_key($_GET['tab']??'overview');$id=absint($_GET['id']??0)?:Engine::latest();$s=Engine::settings();$notice=get_transient('wpr_static_notice_'.get_current_user_id());delete_transient('wpr_static_notice_'.get_current_user_id());
        echo '<div class="wrap wpr-static"><h1>Static Site Generator for WordPress <span class="wpr-version">'.esc_html(WPR_STATIC_VERSION).'</span></h1><p class="description">';self::e('Static frontend on your existing domain. No migration required.','Статический фронтенд WordPress на вашем домене. Без переноса сайта.');echo '</p>';
        if($notice)echo '<div class="notice notice-'.($notice['ok']?'success':'error').' is-dismissible"><p>'.esc_html($notice['msg']).'</p></div>';
        $tabs=['overview'=>['Overview','Обзор'],'doctor'=>['Readiness','Диагностика'],'settings'=>['Settings','Настройки'],'history'=>['Build history','История сборок'],'logs'=>['Reports & logs','Отчёты и журнал'],'help'=>['Help','Помощь']];echo '<nav class="nav-tab-wrapper">';foreach($tabs as $key=>$names)echo '<a class="nav-tab '.($tab===$key?'nav-tab-active':'').'" href="'.esc_url(self::url(['tab'=>$key,'id'=>$id])).'">'.esc_html(self::t(...$names)).'</a>';echo '</nav><div class="wpr-panel">';
        try{if($tab==='settings')self::settings($s);elseif($tab==='doctor')self::doctor();elseif($tab==='history')self::history();elseif($tab==='logs')self::logs($id);elseif($tab==='help')self::help();else self::overview($id);}catch(\Throwable $e){echo '<div class="notice notice-error inline"><p>'.esc_html($e->getMessage()).'</p></div>';}echo '</div></div>';
    }
    private static function settings(array $s):void{echo '<h2>';self::e('Export configuration','Настройки экспорта');echo '</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';self::hidden('save',0,'settings');self::field('destination','Public URL','Публичный URL',$s['destination'],'url','https://static.example.com');echo '<label class="wpr-field"><strong>';self::e('Link mode','Режим ссылок');echo '</strong><select name="mode"><option value="absolute" '.selected($s['mode'],'absolute',false).'>'.esc_html(self::t('Absolute','Абсолютные')).'</option><option value="relative" '.selected($s['mode'],'relative',false).'>'.esc_html(self::t('Relative','Относительные')).'</option></select></label>';self::field('local','Local publish directory','Локальная папка публикации',$s['local'],'text',self::t('Dedicated empty or managed directory outside WordPress.','Отдельная пустая или управляемая директория вне WordPress.'));self::field('exclude','Excluded URL paths (one per line)','Исключения URL (по одному в строке)',str_replace('\\n',"\n",$s['exclude']),'textarea','/account/*');self::field('include','Additional public URLs','Дополнительные публичные URL',$s['include'],'textarea');self::field('types','Excluded post types','Исключённые типы записей',$s['types'],'textarea');echo '<details><summary>';self::e('Advanced limits','Расширенные ограничения');echo '</summary>';self::field('limit','Maximum queue items','Максимум элементов очереди',$s['limit'],'number');self::field('max_mb','Maximum response size (MiB)','Максимальный размер ответа (МиБ)',$s['max_mb'],'number');self::field('retain','Build retention target','Целевое число хранимых сборок',$s['retain'],'number',self::t('Old frontend builds are cleaned automatically after a successful build; export builds are kept.','Старые сборки фронтенда очищаются после успешной генерации; экспортные сборки сохраняются.'));echo '</details><p><button class="button button-primary">';self::e('Save settings','Сохранить настройки');echo '</button></p></form>';}
    private static function doctor():void{echo '<h2>Static Readiness Check</h2><p>';self::e('Check the server and public homepage before building.','Проверьте сервер и публичную главную страницу перед генерацией.');echo '</p>';self::form('doctor','Run diagnostics','Запустить диагностику',0,'doctor',true);$r=get_transient('wpr_static_doctor_'.get_current_user_id());if(!$r)return;echo '<table class="widefat striped"><thead><tr><th>Code</th><th>';self::e('Status','Статус');echo '</th><th>';self::e('Details','Подробности');echo '</th></tr></thead><tbody>';foreach($r as $item)echo '<tr><td><code>'.esc_html($item['code']).'</code></td><td><span class="wpr-status wpr-'.esc_attr($item['level']).'">'.esc_html($item['level']).'</span></td><td>'.esc_html($item['message']).'</td></tr>';echo '</tbody></table>';}
    private static function frontendPanel():void {
        $s=Frontend::get();$enabled=!empty($s['enabled']);$live=$enabled&&!empty($s['active_id']);$active=Engine::active();
        $delivery=$s['delivery']??'wordpress';$labels=['apache+early-php'=>['Apache HTML + early PHP fallback','Apache HTML + ранний PHP-режим'],'apache+wordpress-php'=>['Apache HTML + WordPress fallback','Apache HTML + резервный WordPress'],'early-php'=>['Early PHP (before database initialization)','Ранняя PHP-выдача (до инициализации БД)'],'wordpress-php'=>['PHP through WordPress','PHP через WordPress'],'wordpress'=>['Normal WordPress','Обычный WordPress']];
        echo '<section class="wpr-front"><div class="wpr-heading"><div><p class="wpr-eyebrow">STATIC SITE GENERATOR</p><h2>';self::e('Static frontend','Статический фронтенд');echo '</h2><p>';self::e('Keep your domain, design and WordPress editor.','Сохраните домен, дизайн и редактор WordPress.');echo '</p></div><span class="wpr-status '.($live?'wpr-ok':'wpr-warning').'">'.esc_html($live?self::t('Static mode active','Статический режим активен'):($enabled?self::t('Waiting for a validated build','Ожидается проверенная сборка'):self::t('Static mode off','Статический режим выключен'))).'</span></div>';
        echo '<div class="wpr-grid"><div class="wpr-metric"><small>';self::e('Site address','Адрес сайта');echo '</small><b>'.esc_html(home_url('/')).'</b></div><div class="wpr-metric"><small>';self::e('Delivery mode','Режим выдачи');echo '</small><b>'.esc_html(self::t(...($labels[$live?$delivery:'wordpress']??$labels['wordpress']))).'</b></div><div class="wpr-metric"><small>';self::e('Eligible HTML routes','Статические страницы');echo '</small><strong>'.esc_html($live?(string)($s['routes']??0):'0').'</strong>';if($live&&!empty($s['direct_routes']))echo '<small>'.esc_html(self::t('Direct Apache: ','Напрямую Apache: ').$s['direct_routes']).'</small>';echo '</div></div>';
        if(!empty($s['error']))echo '<div class="notice notice-error inline"><p>'.esc_html($s['error']).'</p></div>';if($live&&!empty($s['note']))echo '<p class="description">'.esc_html(self::t('Direct server mode: ','Прямой режим веб-сервера: ').$s['note']).'</p>';
        if(!$enabled)self::form('enable_frontend','Enable static mode','Включить статический режим',0,'overview',true);else{if(!$active)self::form('rebuild_frontend','Rebuild static frontend','Пересобрать статический сайт',0,'overview',true);self::form('disable_frontend','Disable static mode','Выключить статический режим');self::form(!empty($s['auto'])?'auto_off':'auto_on',!empty($s['auto'])?'Auto rebuild: on':'Auto rebuild: off',!empty($s['auto'])?'Автообновление: включено':'Автообновление: выключено');}
        echo '<p class="description">';self::e('Anonymous GET/HEAD requests only. Cookies, query parameters, forms requiring a server and excluded routes use WordPress. Content changes temporarily restore WordPress until a new build is validated.','Статика выдаётся для подходящих анонимных GET/HEAD-запросов. Cookies, параметры и динамические страницы обрабатывает WordPress. После изменения контента обычная выдача временно восстанавливается до проверки новой сборки.');echo '</p></section>';
    }
    private static function overview(int $id):void{self::frontendPanel();$active=Engine::active();if($active)$id=$active;echo '<div class="wpr-heading"><div><h2>';self::e('Static site','Статический сайт');echo '</h2><p>';self::e('Generation does not change the live WordPress site.','Генерация не изменяет исходный сайт WordPress.');echo '</p></div>';if(!$active)self::form('build','Build portable export','Создать сборку для ZIP',0,'overview',true);echo '</div>';if(!$id){echo '<div class="wpr-empty"><h3>';self::e('Create your first build','Создайте первую сборку');echo '</h3><p>';self::e('Enable the static frontend above, or build a separate portable export.','Включите статический режим выше или создайте отдельную сборку для экспорта.');echo '</p><a class="button" href="'.esc_url(self::url(['tab'=>'settings'])).'">';self::e('Settings','Настройки');echo '</a></div>';return;}$b=Engine::stats($id);$counts=['html'=>0,'asset'=>0,'404'=>0];$bytes=0;$total=0;$done=0;foreach($b['counts'] as $r){$total+=(int)$r['total'];if($r['state']==='done'){$done+=(int)$r['total'];$bytes+=(int)$r['bytes'];if(isset($counts[$r['kind']]))$counts[$r['kind']]+=(int)$r['total'];}}echo '<div id="wpr-build" data-id="'.esc_attr($id).'" data-status="'.esc_attr($b['status']).'"><div class="wpr-heading"><h3>Build #'.esc_html($id).' <span id="wpr-state" class="wpr-status wpr-'.esc_attr($b['status']).'">'.esc_html($b['status']).'</span></h3><span>'.esc_html($b['created']).' UTC</span></div><div class="wpr-grid">';foreach([[self::t('Pages','Страницы'),$counts['html'],'wpr-pages'],[self::t('Assets','Ресурсы'),$counts['asset'],'wpr-assets'],[self::t('Size','Объём'),size_format($bytes),'wpr-size'],[self::t('Queue completed','Обработано задач'),$done.' / '.$total,'wpr-progress']] as $v)echo '<div class="wpr-metric"><small>'.esc_html($v[0]).'</small><strong id="'.esc_attr($v[2]).'">'.esc_html($v[1]).'</strong></div>';echo '</div><p id="wpr-message"></p><p>';self::e('Last activity: ','Последняя активность: ');echo '<span id="wpr-updated">'.esc_html($b['updated']).'</span> UTC</p><div class="wpr-actions">';if(in_array($b['status'],['pending','processing','validating'],true))self::form('pause','Pause','Приостановить',$id);if($b['status']==='paused')self::form('resume','Resume','Продолжить',$id);if(in_array($b['status'],Engine::ACTIVE,true))self::form('cancel','Cancel','Отменить',$id);if($b['status']==='ready'&&!empty(Engine::build($id)['config']['frontend'])){self::form('manifest','Manifest','Манифест',$id);}if($b['status']==='ready'&&empty(Engine::build($id)['config']['frontend'])){self::form('export','Download ZIP','Скачать ZIP',$id,'overview',true);self::form('publish','Publish locally','Опубликовать локально',$id);self::form('manifest','Manifest','Манифест',$id);}self::form('report','Download report','Скачать отчёт',$id);echo '<a class="button" href="'.esc_url(self::url(['tab'=>'logs','id'=>$id])).'">';self::e('View log','Журнал');echo '</a></div>';if($b['published'])echo '<p>'.esc_html(self::t('Last published: ','Опубликовано: ').$b['published']).' UTC</p>';echo '</div>';}
    private static function history():void{echo '<h2>';self::e('Build history','История сборок');echo '</h2><table class="widefat striped"><thead><tr><th>ID</th><th>';self::e('Status','Статус');echo '</th><th>';self::e('Created (UTC)','Создано (UTC)');echo '</th><th>';self::e('Published','Публикация');echo '</th><th>';self::e('Actions','Действия');echo '</th></tr></thead><tbody>';foreach(Engine::history() as $b){echo '<tr><td><a href="'.esc_url(self::url(['id'=>$b['id']])).'">#'.esc_html($b['id']).'</a></td><td>'.esc_html($b['status']).'</td><td>'.esc_html($b['created']).'</td><td>'.esc_html($b['published']??'—').'</td><td>';if(!in_array($b['status'],Engine::ACTIVE,true)&&(int)(Frontend::get()['active_id']??0)!==(int)$b['id'])self::form('delete','Delete','Удалить',(int)$b['id'],'history');echo '</td></tr>';}echo '</tbody></table>';}
    private static function logs(int $id):void{if(!$id)return;echo '<h2>';self::e('Report for build #','Отчёт сборки #');echo esc_html($id).'</h2>';self::form('report','Download JSON','Скачать JSON',$id,'logs');echo '<table class="widefat striped"><thead><tr><th>UTC</th><th>Level</th><th>Code</th><th>';self::e('Details','Подробности');echo '</th></tr></thead><tbody>';foreach(Engine::logs($id) as $r)echo '<tr><td>'.esc_html($r['created']).'</td><td>'.esc_html($r['level']).'</td><td><code>'.esc_html($r['code']).'</code></td><td>'.esc_html($r['message']).'<br><small>'.esc_html($r['url']).'</small></td></tr>';echo '</tbody></table>';}
    private static function help():void{echo '<h2>';self::e('Getting started','Начало работы');echo '</h2><p>';self::e('Enable static mode on the overview. The plugin generates and validates public HTML, then serves eligible anonymous requests on the same domain. For ZIP, create a separate portable export build.','На главной странице включите статический режим. Плагин сгенерирует и проверит HTML, затем будет выдавать подходящие страницы на текущем домене. Для ZIP создайте отдельную экспортную сборку.');echo '</p><p>';self::e('Forms, account pages, server-side search and cart do not become static. External assets and runtime scripts may need separate configuration.','Формы, личный кабинет, серверный поиск и корзина не становятся статическими. Внешние ресурсы и выполняемые в браузере скрипты могут требовать отдельной настройки.');echo '</p><p><code>wp wpr-static doctor</code> · <code>wp wpr-static build</code> · <code>wp wpr-static export</code></p><p><a href="https://xn----ctbgf6biedka.xn--p1ai/">ворд-пресс.рф</a></p>';}
}
